sys_ux_data_broker_transform.script:
function transform(input) {
    // Define OS parent categories and their patterns for grouping


	// Object to store raw OS counts
var osTallies = {};

// GlideAggregate to group by 'os' and count occurrences
var serverAgg = new GlideAggregate('cmdb_ci_server');
serverAgg.addAggregate('COUNT', 'os');
serverAgg.addNotNullQuery('os');
serverAgg.groupBy('os');
serverAgg.query();

// Collect raw OS counts
while (serverAgg.next()) {
    var osValue = serverAgg.getValue('os') + '';
    var osCount = parseInt(serverAgg.getAggregate('COUNT', 'os'), 10) || 0;
    osTallies[osValue] = osCount;
}

// Dynamic object to store grouped names and counts
var groupedSystems = {};

// Process OS names to group similar ones
var osNames = Object.keys(osTallies);
osNames.sort((a, b) => a.length - b.length); // Sort by length, shortest first

for (var i = 0; i < osNames.length; i++) {
    var currentOs = osNames[i].toLowerCase().trim();
    var rootName = currentOs.split(/\s+/)[0]; // Take first word as potential base
    var count = osTallies[osNames[i]];

    // Check if this OS belongs to an existing group
    var foundGroup = false;
    for (var group in groupedSystems) {
        if (currentOs.includes(group.toLowerCase())) {
            groupedSystems[group] += count;
            foundGroup = true;
            break;
        }
    }

    // If no group found, create a new one with the root name
    if (!foundGroup) {
        var capitalizedRoot = rootName.charAt(0).toUpperCase() + rootName.slice(1);
        groupedSystems[capitalizedRoot] = count;
    }
}

// Prepare the data array in the required format
var chartData = [];
var chartElements = [];

for (var groupName in groupedSystems) {
    if (groupedSystems.hasOwnProperty(groupName) && groupedSystems[groupName] > 0) {
        // Add to data array
        chartData.push({
            "assignment_group": groupName,
            "value": groupedSystems[groupName].toString()
        });

        // Add to elements array (using groupName as both label and query base)
        chartElements.push({
            "eventData": {
                "query": "os LIKE " + groupName
            },
            "label": groupName,
            "id": groupName.toLowerCase().replace(/\s+/g, '_') // Simple ID based on name
        });
    }
}

// Construct the final output in the specified format
var result = [{
    "data": chartData,
    "metadata": {
        "eventData": {
            "table": "cmdb_ci_server"
        },
        "dataSourceLabel": "Server OS Distribution",
        "groupBy": [
            {
                "series": [
                    {
                        "label": "Count",
                        "id": "value",
                        "type": "value"
                    }
                ],
                "elements": chartElements,
                "label": "Operating System",
                "id": "assignment_group",
                "fieldType": "string" // Using string since these are OS names, not references
            }
        ],
        "format": {
            "unitFormat": "{0}"
        },
        "aggregateBy": 4,
        "metricId": gs.generateGUID() // Generate a unique ID
    }
}];

// Print the result for verification (optional)
gs.info(JSON.stringify(result, null, 4));

// Return the result (for use in a script include or other context)
return result;
     }
